<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ChartPulse — Track All Markets</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1a1a2e;
  --bg-hover: #1e1e3a;
  --accent: #2962FF;
  --accent-hover: #1e4fdb;
  --text-primary: #EAEAEA;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --gain: #00C853;
  --loss: #F7525F;
  --border: #2a2a4a;
  --border-light: #333355;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
}
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--accent); text-decoration: none; }
a:hover { color: var(--accent-hover); }
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

/* Nav */
.nav { position: sticky; top: 0; z-index: 100; background: rgba(15,15,15,0.92); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); }
.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 60px; max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.nav-brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 20px; color: var(--text-primary); }
.nav-brand svg { width: 28px; height: 28px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { color: var(--text-secondary); font-size: 14px; font-weight: 500; transition: color 0.15s; }
.nav-links a:hover, .nav-links a.active { color: var(--text-primary); }
.nav-cta { display: flex; align-items: center; gap: 12px; }
.nav-cta .btn-signup { background: var(--accent); color: #fff; border: none; padding: 8px 18px; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; transition: background 0.15s; }
.nav-cta .btn-signup:hover { background: var(--accent-hover); }
.nav-cta .btn-login { color: var(--text-secondary); font-size: 14px; font-weight: 500; cursor: pointer; background: none; border: none; }
.nav-cta .btn-login:hover { color: var(--text-primary); }

/* Hero */
.hero { padding: 80px 0 60px; text-align: center; }
.hero h1 { font-size: 48px; font-weight: 700; line-height: 1.15; max-width: 800px; margin: 0 auto 20px; letter-spacing: -0.02em; }
.hero p { font-size: 18px; color: var(--text-secondary); max-width: 640px; margin: 0 auto 36px; line-height: 1.6; }
.hero-btns { display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap; }
.btn-primary { background: var(--accent); color: #fff; border: none; padding: 14px 28px; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; transition: background 0.15s; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-secondary { background: transparent; color: var(--text-primary); border: 1px solid var(--border-light); padding: 14px 28px; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; transition: all 0.15s; }
.btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

/* Section Header */
.section { padding: 48px 0; }
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; flex-wrap: wrap; gap: 16px; }
.section-header h2 { font-size: 22px; font-weight: 600; }
.section-header .see-all { font-size: 14px; color: var(--accent); font-weight: 500; cursor: pointer; }

/* Market Summary Tabs */
.market-tabs { display: flex; gap: 4px; margin-bottom: 20px; flex-wrap: wrap; }
.market-tab { padding: 8px 16px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; color: var(--text-secondary); background: transparent; border: none; transition: all 0.15s; }
.market-tab:hover { color: var(--text-primary); background: var(--bg-hover); }
.market-tab.active { background: var(--accent); color: #fff; }

/* Market Summary Cards */
.market-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 12px; }
.market-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 16px; transition: border-color 0.15s; }
.market-card:hover { border-color: var(--accent); }
.market-card .ticker-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.market-card .flag { font-size: 16px; }
.market-card .symbol { font-size: 12px; color: var(--text-muted); font-weight: 500; }
.market-card .name { font-size: 13px; color: var(--text-secondary); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.market-card .price { font-size: 20px; font-weight: 700; margin: 6px 0; font-variant-numeric: tabular-nums; }
.market-card .change { font-size: 13px; font-weight: 600; }
.market-card .change.positive { color: var(--gain); }
.market-card .change.negative { color: var(--loss); }

/* Community Ideas */
.ideas-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
.idea-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px; transition: border-color 0.15s; cursor: pointer; }
.idea-card:hover { border-color: var(--accent); }
.idea-card .author-row { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.idea-card .avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--bg-tertiary); display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 13px; color: var(--accent); }
.idea-card .author-name { font-size: 14px; font-weight: 600; }
.idea-card .idea-time { font-size: 12px; color: var(--text-muted); }
.idea-card .idea-title { font-size: 16px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }
.idea-card .idea-excerpt { font-size: 13px; color: var(--text-secondary); line-height: 1.5; margin-bottom: 12px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.idea-card .idea-ticker { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 4px; font-size: 12px; font-weight: 600; background: var(--bg-tertiary); color: var(--accent); }
.idea-card .idea-meta { display: flex; align-items: center; gap: 16px; font-size: 12px; color: var(--text-muted); margin-top: 12px; }

/* Indicators Section */
.indicators-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
.indicator-item { display: flex; align-items: center; gap: 12px; background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px 16px; transition: border-color 0.15s; cursor: pointer; }
.indicator-item:hover { border-color: var(--accent); }
.indicator-icon { width: 40px; height: 40px; border-radius: 8px; background: var(--bg-tertiary); display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0; }
.indicator-info { flex: 1; min-width: 0; }
.indicator-name { font-size: 14px; font-weight: 600; }
.indicator-desc { font-size: 12px; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.indicator-stars { color: var(--accent); font-size: 12px; }

/* Trending Stocks */
.trending-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
.trending-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 16px; display: flex; align-items: center; justify-content: space-between; transition: border-color 0.15s; cursor: pointer; }
.trending-card:hover { border-color: var(--accent); }
.trending-card .ticker-info { display: flex; flex-direction: column; gap: 2px; }
.trending-card .ticker-name { font-size: 13px; color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 120px; }
.trending-card .price-info { text-align: right; }
.trending-card .price-val { font-size: 16px; font-weight: 700; font-variant-numeric: tabular-nums; }
.trending-card .change-val { font-size: 12px; font-weight: 600; margin-top: 2px; }
.trending-card .change-val.positive { color: var(--gain); }
.trending-card .change-val.negative { color: var(--loss); }

/* Top Stories */
.stories-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
.story-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px; transition: border-color 0.15s; cursor: pointer; }
.story-card:hover { border-color: var(--accent); }
.story-source { font-size: 12px; color: var(--accent); font-weight: 600; margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.05em; }
.story-title { font-size: 15px; font-weight: 600; line-height: 1.4; margin-bottom: 6px; }
.story-time { font-size: 12px; color: var(--text-muted); }

/* Trade Ideas */
.trade-ideas-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
.trade-idea-item { display: flex; align-items: center; justify-content: space-between; background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px 16px; transition: border-color 0.15s; cursor: pointer; }
.trade-idea-item:hover { border-color: var(--accent); }
.trade-idea-item .pair { font-weight: 600; font-size: 14px; }
.trade-idea-item .direction { font-size: 12px; font-weight: 600; padding: 3px 8px; border-radius: 4px; }
.trade-idea-item .direction.buy { background: rgba(0,200,83,0.15); color: var(--gain); }
.trade-idea-item .direction.sell { background: rgba(247,82,95,0.15); color: var(--loss); }

/* Footer */
.footer { background: var(--bg-secondary); border-top: 1px solid var(--border); padding: 48px 0 32px; margin-top: 60px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 32px; margin-bottom: 36px; }
.footer-col h4 { font-size: 13px; font-weight: 600; color: var(--text-primary); margin-bottom: 14px; text-transform: uppercase; letter-spacing: 0.05em; }
.footer-col a { display: block; font-size: 13px; color: var(--text-muted); margin-bottom: 8px; transition: color 0.15s; }
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom { border-top: 1px solid var(--border); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; font-size: 13px; color: var(--text-muted); }

/* Sparkline placeholder */
.sparkline { width: 60px; height: 28px; display: flex; align-items: flex-end; gap: 1px; }
.sparkline-bar { flex: 1; border-radius: 1px; min-height: 2px; }
.sparkline-bar.up { background: var(--gain); }
.sparkline-bar.down { background: var(--loss); }

/* Tab Panel */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* Responsive */
@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 15px; }
  .nav-links { display: none; }
  .market-grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
  .ideas-grid { grid-template-columns: 1fr; }
}
</style>
</head>
