});

// Timeframe toggle
document.querySelectorAll('.timeframe-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.timeframe-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    drawChart(this.dataset.tf);
  });
});

// Financial tabs
document.getElementById('financial-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('panel-tab')) {
    this.querySelectorAll('.panel-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    document.getElementById('financial-annual').style.display = e.target.dataset.fin === 'annual' ? '' : 'none';
    document.getElementById('financial-quarterly').style.display = e.target.dataset.fin === 'quarterly' ? '' : 'none';
  }
});

// Generate candlestick data
function generateCandleData(count, basePrice, volatility) {
  const data = [];
  let price = basePrice;
  for (let i = 0; i < count; i++) {
    const open = price;
    const change = (Math.random() - 0.48) * volatility;
    const close = open + change;
    const wickHigh = Math.max(open, close) + Math.random() * volatility * 0.6;
    const wickLow = Math.min(open, close) - Math.random() * volatility * 0.6;
    data.push({ open, high: wickHigh, low: wickLow, close, volume: Math.random() * 1000000 });
    price = close;
  }
  return data;
}

// Draw candlestick chart
function drawChart(timeframe) {
  const svg = document.getElementById('chart-svg');
  const counts = { '1D': 78, '5D': 65, '1M': 30, '3M': 65, '6M': 130, 'YTD': 90, '1Y': 260, '5Y': 260, 'All': 300 };
  const count = counts[timeframe] || 30;
  const data = generateCandleData(count, 263, 6);

  const w = 900, h = 420;
  const pad = { top: 20, right: 20, bottom: 30, left: 55 };
  const pw = w - pad.left - pad.right;
  const ph = h - pad.top - pad.bottom;

  const allPrices = data.flatMap(d => [d.high, d.low]);
  const minP = Math.min(...allPrices);
  const maxP = Math.max(...allPrices);
  const range = maxP - minP || 1;
  const yScale = val => pad.top + ph * (1 - (val - minP) / range);

  const candleW = Math.max(3, (pw / count) * 0.6);
  const gap = pw / count;

  let html = `<g class="chart-grid">`;
  for (let i = 0; i <= 5; i++) {
    const y = pad.top + (ph / 5) * i;
    const val = maxP - (range / 5) * i;
    html += `<line x1="${pad.left}" y1="${y}" x2="${w-pad.right}" y2="${y}" />`;
    html += `<text x="${pad.left-5}" y="${y+3}" text-anchor="end">${val.toFixed(1)}</text>`;
  }
  html += `</g>`;

  html += `<g class="candles">`;
  data.forEach((d, i) => {
    const x = pad.left + i * gap + gap / 2;
    const yO = yScale(d.open), yC = yScale(d.close);
    const yH = yScale(d.high), yL = yScale(d.low);
    const isBull = d.close >= d.open;
    const color = isBull ? '#00C853' : '#F7525F';
    const bodyTop = Math.min(yO, yC);
    const bodyH = Math.max(Math.abs(yC - yO), 0.5);
    html += `<line x1="${x}" y1="${yH}" x2="${x}" y2="${yL}" stroke="${color}" class="candle-wick" />`;
    html += `<rect x="${x - candleW/2}" y="${bodyTop}" width="${candleW}" height="${bodyH}" fill="${color}" class="candle-body" rx="1" />`;
  });
  html += `</g>`;

  svg.innerHTML = html;
}

// Initial draw
drawChart('1M');

// Resize handling
window.addEventListener('resize', () => {
  const active = document.querySelector('.timeframe-btn.active');
  drawChart(active ? active.dataset.tf : '1M');
});
</script>
