<script>
// Feed tabs (Popular / Editors' picks)
document.getElementById('idea-feed-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('filter-tab')) {
    this.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    document.getElementById('feed-popular').classList.toggle('active', e.target.dataset.feed === 'popular');
    document.getElementById('feed-editors').classList.toggle('active', e.target.dataset.feed === 'editors');
  }
});

// Video only toggle
document.getElementById('video-only').addEventListener('change', function() {
  const cards = document.querySelectorAll('.idea-card');
  cards.forEach(card => {
    if (this.checked) {
      card.style.display = card.dataset.type === 'video' ? '' : 'none';
    } else {
      card.style.display = '';
    }
  });
});

// Asset category filter
document.querySelectorAll('.filter-category').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.filter-category').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    const asset = this.dataset.asset;
    const cards = document.querySelectorAll('.idea-card');
    const videoOnly = document.getElementById('video-only').checked;
    cards.forEach(card => {
      if (asset === 'all') {
        card.style.display = videoOnly && card.dataset.type !== 'video' ? 'none' : '';
      } else {
        const matches = card.dataset.asset === asset;
        const videoOk = !videoOnly || card.dataset.type === 'video';
        card.style.display = matches && videoOk ? '' : 'none';
      }
    });
  });
});

// Pagination
document.querySelectorAll('.page-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    if (this.classList.contains('arrow') || this.textContent === '...') return;
    document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
