document.querySelector('#market-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('asset-tab')) {
    this.querySelectorAll('.asset-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    const sectionId = 'section-' + e.target.dataset.section;
    document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
    const target = document.getElementById(sectionId);
    if (target) target.classList.add('active');
  }
});

// Chart timeframe toggle
document.querySelectorAll('.ctrl-tf').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.ctrl-tf').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
  });
});

// Chart type toggle (Area / Candles)
document.querySelectorAll('.ctrl-type').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.ctrl-type').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
  });
});

// Session tabs (Regular / Pre-market / After-hours)
document.getElementById('session-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('session-tab')) {
    this.querySelectorAll('.session-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    const session = e.target.dataset.session;
    ['regular', 'premarket', 'afterhours'].forEach(s => {
      const gPanel = document.getElementById('gainers-' + s);
      const lPanel = document.getElementById('losers-' + s);
      const show = s === session;
      if (gPanel) gPanel.style.display = show ? '' : 'none';
      if (lPanel) lPanel.style.display = show ? '' : 'none';
    });
  }
});
</script>
