<script>
// Category tabs
document.getElementById('category-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('filter-tab')) {
    this.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    const cat = e.target.dataset.cat;
    const cards = document.querySelectorAll('.broker-card');
    cards.forEach(card => {
      if (cat === 'all') {
        card.style.display = '';
      } else {
        card.style.display = card.dataset.cat.includes(cat) ? '' : 'none';
      }
    });
  }
});

// Rating sort tabs
document.getElementById('rating-tabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('sort-tab')) {
    this.querySelectorAll('.sort-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    const sort = e.target.dataset.sort;
    const container = document.getElementById('broker-listings');
    const cards = Array.from(container.querySelectorAll('.broker-card'));
    if (sort === 'best') {
      cards.sort((a, b) => parseFloat(b.dataset.rating) - parseFloat(a.dataset.rating));
    }
    // For 'all', keep original order by re-indexing
    cards.forEach(card => container.appendChild(card));
  }
});
</script>
